257	
258	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
259	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
260	
261	    /**
262	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
263	     * code are kept when present; otherwise country code '+61' is assumed and a single
264	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
265	     * stripped. The result must be a '+' followed by 8 to 15 digits.
266	     * Returns {@code null} when the number cannot form a valid E.164 value.
267	     */
268	    private static String normalizeTelephone(String telephone) {
269	        if (telephone == null) {
270	            return null;
271	        }
272	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
273	        String e164;
274	        if (cleaned.startsWith("+")) {
275	            e164 = cleaned;
276	        } else {
277	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
278	            e164 = "+61" + national;
279	        }
280	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
281	    }
282	
283	    /**
284	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
285	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
286	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
287	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
288	     */
289	    private String generateCustomerCode(String city, String lastName) {
290	        String city3 = firstThreeLetters(city);
291	        String last3 = firstThreeLetters(lastName);
292	        int sequence = countOwnersInCity(city) + 1;
293	        return String.format("%s-%s-%04d", city3, last3, sequence);
294	    }
295	
296	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
297	    private static String firstThreeLetters(String value) {
298	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
299	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
300	    }
301	
302	    /**
303	     * The number of existing owners registered in {@code city}, compared case-insensitively
304	     * with collapsed whitespace.
305	     */
306	    private int countOwnersInCity(String city) {
307	        String normalized = normalizeHouseholdField(city);
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
310	            .count();
311	    }
312	
313	    /**
314	     * The effective registration date to store for a new owner: the date supplied on the request
315	     * when present, otherwise the current server date, in either case rolled forward to a business
316	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
317	     * This single point of resolution is what every registration-date-derived value (the stored
318	     * date, the membership number's year segment, the per-day create-limit) is computed from.
319	     */
320	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
321	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
322	        return toBusinessDay(date);
323	    }
324	
325	    /**
326	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
327	     * following Monday; a weekday is returned unchanged.
328	     */
329	    private static LocalDate toBusinessDay(LocalDate date) {
330	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
331	            date = date.plusDays(1);
332	        }
333	        return date;
334	    }
335	
336	    /**
337	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
338	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
339	     */
340	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
341	        String yy = String.format("%02d", registrationDate.getYear() % 100);
342	        return customerCode + "-M" + yy;
343	    }
344	
345	    /**
346	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
347	     * last name, compared case-insensitively.
348	     */
349	    private int countNamesakes(Owner owner) {
350	        String firstName = normalizeHouseholdField(owner.getFirstName());
351	        String lastName = normalizeHouseholdField(owner.getLastName());
352	        return (int) this.clinicService.findAllOwners().stream()
353	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
354	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
355	            .count();
356	    }
357	
358	    /** The number of existing owners whose registration date is {@code date}. */
359	    private int countOwnersRegisteredOn(LocalDate date) {
360	        return (int) this.clinicService.findAllOwners().stream()
361	            .filter(existing -> date.equals(existing.getRegistrationDate()))
362	            .count();
363	    }
364	
365	    /** Whether any existing owner already uses the given (E.164) telephone number. */
366	    private boolean isTelephoneInUse(String telephone) {
367	        return this.clinicService.findAllOwners().stream()
368	            .map(Owner::getTelephone)
369	            .filter(existing -> existing != null)
370	            .map(OwnerRestControllerV1::normalizeTelephone)
371	            .filter(existing -> existing != null)
372	            .anyMatch(telephone::equals);
373	    }
374	
375	    /** Common street-type abbreviations expanded during address normalization. */
376	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
377	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
378	
379	    /**
380	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
381	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
382	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
383	     * string when {@code address} is null or blank after normalization.
384	     */
385	    private static String normalizeAddress(String address) {
386	        if (address == null) {
387	            return "";
388	        }
389	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
390	        if (collapsed.isEmpty()) {
391	            return "";
392	        }
393	        StringBuilder sb = new StringBuilder(collapsed.length());
394	        for (String token : collapsed.split(" ")) {
395	            if (sb.length() > 0) {
396	                sb.append(' ');
397	            }
398	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
399	        }
400	        return sb.toString();
401	    }
402	
403	    /**
404	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
405	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
406	     */
407	    private static String normalizeHouseholdField(String value) {
408	        if (value == null) {
409	            return "";
410	        }
411	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
412	    }
413	
414	    /**
415	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
416	     * same address compared case-insensitively with collapsed whitespace.
417	     */
418	    private List<Owner> findHousemates(Owner owner) {
419	        String lastName = normalizeHouseholdField(owner.getLastName());
420	        String address = normalizeHouseholdField(owner.getAddress());
421	        return this.clinicService.findAllOwners().stream()
422	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
423	                && normalizeHouseholdField(existing.getAddress()).equals(address))
424	            .toList();
425	    }
426	
427	    /**
428	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
429	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
430	     */
431	    private boolean isHouseholdInUse(Owner owner) {
432	        return !findHousemates(owner).isEmpty();
433	    }
434	
435	    /**
436	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
437	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
438	     * deterministically from those normalized fields so housemates always resolve to the same value,
439	     * regardless of registration order.
440	     */
441	    private static String householdId(Owner owner) {
442	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
443	            + normalizeHouseholdField(owner.getAddress());
444	        try {
445	            byte[] digest = MessageDigest.getInstance("SHA-256")
446	                .digest(key.getBytes(StandardCharsets.UTF_8));
447	            StringBuilder sb = new StringBuilder(24);
448	            for (int i = 0; i < 12; i++) {
449	                sb.append(String.format("%02X", digest[i]));
450	            }
451	            return sb.toString();
452	        }
453	        catch (NoSuchAlgorithmException e) {
454	            throw new IllegalStateException("SHA-256 not available", e);
455	        }
456	    }
457	}
